  "general.languageFailed": "Impossibile salvare la lingua. {error}",
  "computer.introLinux": "Ogni bot ha il suo computer Linux: un desktop completo con browser, terminale e i suoi file, separato da tutti gli altri bot e da questo server. I computer vanno in sospensione quando sono inattivi e si riattivano quando serve; non si perde nulla. Puoi guardare o prendere il controllo in qualsiasi momento.",
  "computer.introBrowser": "Ogni bot ha il suo browser su questo server: una finestra privata che usa per aprire pagine, compilare moduli e leggere cosa c'è sullo schermo. Puoi guardare o prendere il controllo in qualsiasi momento.",
  "computer.noneTitle": "Nessun computer disponibile",
