  "computer.footLinux_one": "Cancella elimina quel computer con tutto ciò che vi è installato e salvato, tranne i file della libreria del bot; la prossima volta ne viene creato uno pulito. Solo {n} computer può essere attivo alla volta: quello inutilizzato da più tempo va in sospensione.",
  "computer.footLinux_other": "Cancella elimina quel computer con tutto ciò che vi è installato e salvato, tranne i file della libreria del bot; la prossima volta ne viene creato uno pulito. Fino a {n} computer possono essere attivi alla volta: quello inutilizzato da più tempo va in sospensione.",
