  "permissions.intro": "Decisioni permanenti su cosa i tuoi bot possono fare senza chiedere. Pagamenti ed eliminazioni chiedono sempre, e così anche, dopo che un bot ha letto contenuti esterni, scrivere a qualcuno che non hai mai nominato o agire sul tuo computer, qualunque cosa sia salvata qui.",
