  "relay.intro": "I tuoi computer, collegati con l'app Sklubot Relais. Un bot può guardare lo schermo, cliccare, scrivere ed eseguire comandi solo con il tuo OK: chiesto qui, e chiesto di nuovo sul computer stesso.",
