  "relay.phoneTitle": "Un telefono? (Android)",
  "relay.phoneSteps": "Installa l'app Android di Sklubot (Impostazioni → Generale → Sul tuo telefono), attiva il suo servizio di accessibilità, poi nell'app apri Controllo del telefono e attiva il relay: mostra un codice da digitare qui sopra. I bot potranno quindi fare screenshot, toccare, scorrere, scrivere e aprire app, dopo il tuo sì sul telefono; mai comandi. iPhone: non possibile, iOS non lo consente.",
  "relay.phoneOpen": "Collega questo telefono",
