  "relay.guard.terminalOff": "Disattivato: nessun bot può eseguire comandi su questo computer.",
  "relay.guard.terminalOn": "Attivato: il bot può eseguire comandi (per programmare, ad esempio). Ognuno ti viene mostrato su una scheda con la sua cartella; quelli delicati (eliminazioni, diritti di amministratore, installazioni per tutto il computer…) vengono sempre chiesti, e il computer chiede anche una volta per sessione. Le finestre del terminale restano vietate per clic e digitazione.",
  "relay.guard.keepApps": "App da tenere fuori portata",
  "relay.guard.keepAppsPh": "Una per riga, per esempio:\nLa mia banca\nSignal",
