  "egress.accountIntro": "I programmi sul computer di un bot possono chiamare le tue API senza mai tenere la chiave: attivalo per ogni bot (impostazioni del bot → Lettura e chiavi). Sklubot aggiunge la chiave fuori dal computer, solo per gli host per cui è salvata, e ti chiede prima del primo uso di ogni chiave.",
  "egress.toggle": "I programmi possono usare le mie chiavi",
  "egress.intro": "Script e strumenti che {name} esegue sul suo computer possono chiamare API con i tuoi secret salvati tramite Sklubot. La chiave non entra mai nel computer; funzionano solo gli host di ogni secret; il primo uso di ogni secret, e i cambi dopo contenuti esterni, ti vengono chiesti.",
