  "backup.title": "Backup automatico",
  "backup.intro": "Ogni notte, Sklubot stesso invia una copia cifrata dei suoi dati a uno storage S3 fuori da questo server (OVHcloud, Hetzner, Scaleway…). Solo tu (che gestisci il server) vedi questa impostazione.",
