  "backup.step1": "La chiave di backup",
  "backup.keyWhy": "I backup vengono cifrati prima di lasciare questo server. Qui crei una chiave in due parti: la parte pubblica resta sul server (può solo cifrare), la parte privata resta a te (solo lei può ripristinare). Anche chi si prende il server o lo storage non può leggere i tuoi backup.",
  "backup.makeKey": "Crea la mia chiave di backup",
  "backup.noWebCrypto": "Questo browser non può creare la chiave. Apri questa pagina in un browser recente (Chrome, Firefox, Safari aggiornati), o incolla una chiave pubblica age.",
