  "backup.guide.ovh.title": "Crea il bucket e le chiavi su OVHcloud (da telefono)",
  "backup.guide.ovh.1": "OVHcloud Control Panel → Public Cloud → il tuo progetto → Storage → Object Storage.",
  "backup.guide.ovh.2": "Scheda «Users»: crea un utente Object Storage. Annota la chiave di accesso e la chiave segreta (pulsante … → «View the secret key»).",
  "backup.guide.ovh.3": "Scheda «Containers» → «Create an object container»: tipo «S3-compatible API», un nome in minuscolo (es. sklubot-backups), una regione (es. Gravelines = gra), collega l'utente, poi «Create».",
  "backup.guide.ovh.4": "Qui: scegli la stessa regione, il nome del bucket, la chiave di accesso e la chiave segreta, poi «Prova la connessione».",
  "backup.guide.hetzner.title": "Crea il bucket e le chiavi su Hetzner (da telefono)",
  "backup.guide.hetzner.1": "Hetzner Console → il tuo progetto → Object Storage → «Create Bucket»: una posizione (es. Falkenstein = fsn1), un nome unico, visibilità «private», poi «Create & Buy now».",
  "backup.guide.hetzner.2": "Menu «Security» → scheda «S3 Credentials» → «Generate credentials», con una descrizione (es. Sklubot).",
  "backup.guide.hetzner.3": "Copia subito la chiave di accesso (in alto) e la chiave segreta (in basso): la chiave segreta non viene mostrata di nuovo.",
  "backup.guide.hetzner.4": "Qui: scegli la stessa posizione, il nome del bucket ed entrambe le chiavi, poi «Prova la connessione».",
  "backup.guide.scaleway.title": "Crea il bucket e le chiavi su Scaleway (da telefono)",
  "backup.guide.scaleway.1": "Console Scaleway → Object Storage → «+ Create bucket»: una regione (es. Parigi = fr-par), un nome, visibilità «Private», poi «Create bucket».",
  "backup.guide.scaleway.2": "Menu dell'account (in alto a destra) → «IAM & API keys» → scheda «API keys» → «+ Generate API key».",
  "backup.guide.scaleway.3": "Per Object Storage, scegli il progetto del bucket come progetto preferito, poi «Generate API key». Copia la chiave di accesso e la chiave segreta (mostrate una volta).",
  "backup.guide.scaleway.4": "Qui: scegli la stessa regione, il nome del bucket ed entrambe le chiavi, poi «Prova la connessione».",
  "backup.step3": "Quando, e quanti conservarne",
