  "backup.restoreTitle": "Ripristina un backup",
  "backup.restore1": "Ti servono il file della tua chiave privata, l'accesso allo storage e un server con Sklubot (anche vuoto).",
  "backup.restore2": "Sul server, con SKLUBOT_S3_ENDPOINT, SKLUBOT_S3_REGION, SKLUBOT_S3_BUCKET, SKLUBOT_S3_PREFIX, SKLUBOT_S3_ACCESS_KEY e SKLUBOT_S3_SECRET_KEY impostate, questo comando scarica l'ultimo backup e lo verifica:",
  "backup.restore3": "Poi deploy/restore.sh <file>.age (o deploy/restore-drill.sh per una prova senza rischi) con SKLUBOT_BACKUP_AGE_IDENTITY=key.txt. Passo per passo: docs/SAUVEGARDE.md.",
