  "caps.heading": "Limiti di consumo",
  "caps.intro": "Limiti a ciò che usi in un giorno e in un mese, in dollari e/o in token, per tutto l'account o per un bot (le sue attività in background contano con lui). Giorni e mesi seguono il tuo fuso orario ({tz}, dal tuo profilo). I limiti in token coprono anche i turni di Claude Code e Codex, che qui non costano nulla.",
