  "caps.diffCaps": "Limiti: al giorno o al mese (il tuo fuso orario), in dollari o token, per l'account o per un bot; fermano solo il lavoro non presidiato, o tutto. Possono valerne diversi: il primo raggiunto ferma il lavoro.",
  "caps.diffBudget": "Budget mensile (sotto): il limite in dollari dell'account per mese di calendario in UTC; una volta speso, si ferma tutto. Resta com'era.",
