  "lp.trust.kicker": "Fiducia",
  "lp.trust.title": "Pensato perché tu possa affidargli lavoro vero.",
  "lp.trust.t1t": "Account separati",
  "lp.trust.t1": "Ogni account vede solo i propri bot, file e conversazioni. I computer dei bot sono container separati, su una rete in cui non possono vedersi.",
  "lp.trust.t2t": "Segreti cifrati",
  "lp.trust.t2": "Le connessioni alle app e le password salvate sono cifrate sul server (AES-256-GCM).",
  "lp.trust.t3t": "Software libero, ospitabile in Europa",
  "lp.trust.t3": "Sklubot è rilasciato con licenza MIT e gira sul server che scegli, in Francia o altrove in Europa.",
  "lp.trust.t4t": "Resti al comando",
  "lp.trust.t4": "Un registro di ogni azione, un pulsante Pausa, tetti di spesa e il tuo via libera prima di tutto ciò che non si può annullare.",
  "lp.faq.kicker": "FAQ",
  "lp.faq.title": "Le domande che ci fanno.",
  "lp.faq.q1": "Cos'è un bot su Sklubot?",
  "lp.faq.a1": "Un assistente IA con un ruolo, una memoria, strumenti e, a seconda del piano, un computer. Gli parli come a un collega; può anche lavorare da solo, con una routine programmata o verso un obiettivo.",
  "lp.faq.q2": "Un bot può combinare guai?",
  "lp.faq.a2": "Un nuovo bot è prudente: chiede prima di agire. Per tutto ciò che non si può annullare (inviare, pagare, eliminare, pubblicare) si ferma e aspetta il tuo via libera, senza «consenti sempre». Puoi metterlo in pausa in qualsiasi momento.",
  "lp.faq.q3": "Posso davvero parlare con i miei bot?",
  "lp.faq.a3": "Sì: chiama un bot dalla sua conversazione e parlagli a voce. Risponde con la voce che hai scelto per lui. Puoi anche scrivergli, quando vuoi.",
  "lp.faq.q4": "Devo installare qualcosa?",
  "lp.faq.a4": "No: tutto funziona nel browser, su un computer o un telefono. Se preferisci, c'è un'app per Windows e Linux, e una per Android.",
  "lp.faq.q5": "Windows mi avvisa quando installo l'app. È normale?",
  "lp.faq.a5": "Sì. L'app non è ancora firmata, quindi Windows SmartScreen mostra un avviso la prima volta. Clicca «Ulteriori informazioni», poi «Esegui comunque». Puoi anche usare Sklubot online, senza installare nulla.",
  "lp.faq.q6": "Quali modelli IA vengono usati?",
  "lp.faq.a6": "I modelli IA offerti da questo servizio, o la tua chiave API se preferisci. Ogni bot può avere il suo modello e modelli di riserva.",
  "lp.faq.q7": "Dove sono i miei dati?",
  "lp.faq.a7": "Sul server di questo servizio. Dalle impostazioni puoi esportare i tuoi dati o eliminare il tuo account in qualsiasi momento.",
  "lp.faq.q8": "Perché confermare il mio indirizzo email?",
  "lp.faq.a8": "Per essere sicuri che sia davvero tu, e per aiutarti se dimentichi la password. Puoi guardarti intorno subito; i tuoi bot iniziano a lavorare appena è confermato.",
  "lp.final.title": "La tua squadra ti aspetta.",
  "lp.final.sub": "Crea il tuo account, scegli un modello, affida un primo compito.",
  "lp.foot.tag": "Una squadra di bot IA, con la loro memoria, i loro strumenti, il loro computer e la loro voce.",
